/**
 * Ported WordPress page bodies, generated by scripts/gen-pages.py.
 * Static imports so every page prerenders at build time.
 */
import fullData from '@/content/pages-full.json';

export type WpPage = {
  slug: string;
  title: string;
  seoTitle: string;
  seoDescription: string;
  html: string;
};

const full = fullData as Record<string, WpPage>;

export function getPage(slug: string): WpPage | undefined {
  return full[slug];
}
